extends Node3D

@export var light_color: Color = Color.WHITE
@export var target_path: NodePath

func _ready() -> void:
	var target_root = _resolve_target_root()

	# Find SpotLight3D in the target flashlight
	var spot = _find_spot_light(target_root)
	if spot:
		spot.light_color = light_color

func _find_spot_light(node: Node) -> SpotLight3D:
	for child in node.get_children():
		if child is SpotLight3D:
			return child
		var found = _find_spot_light(child)
		if found:
			return found
	return null

func _resolve_target_root() -> Node:
	if target_path != NodePath():
		var explicit = get_node_or_null(target_path)
		if explicit:
			return explicit
	if _find_spot_light(self):
		return self
	var parent = get_parent()
	if parent and _find_spot_light(parent):
		return parent
	return self

# Also tint the lens to match
var lens = _find_lens_mesh(target_root)
if lens and lens is MeshInstance3D:
	var mat = StandardMaterial3D.new()
	mat.albedo_color = light_color.lerp(Color.WHITE, 0.5)
	mat.emission_enabled = true
	mat.emission = light_color * 0.5
	mat.emission_energy_multiplier = 1.0
	mat.metallic = 0.1
	mat.roughness = 0.1
	lens.material_override = mat

func _find_lens_mesh(node: Node) -> MeshInstance3D:
	for child in node.get_children():
		if child is MeshInstance3D and child.name == "LensMesh":
			return child
		var found = _find_lens_mesh(child)
		if found:
			return found
	return null

func _ready() -> void:
	var target_root = _resolve_target_root()
	var spot = _find_spot_light(target_root)
	if spot:
		spot.light_color = light_color
	# ... and done.
	#
	# No _process, no tween, no runtime change.
	# The color is the flashlight's identity, set once,
	# held forever. The player changes color by
	# picking up a different flashlight.

func apply_grid_config(config: Dictionary) -> void:
	pass  # Even grid config doesn't override color.
	      # Color belongs to this specific instance.

func _resolve_target_root() -> Node:
	# Priority 1: explicit target_path if set
	if target_path != NodePath():
		var explicit = get_node_or_null(target_path)
		if explicit:
			return explicit

	# Priority 2: self contains the SpotLight3D
	if _find_spot_light(self):
		return self

	# Priority 3: parent contains it (this script is a sibling)
	var parent = get_parent()
	if parent and _find_spot_light(parent):
		return parent

	# Default: use self anyway so _find_spot_light logs the warning
	return self
